"檢點人員首頁": "Inspector Home",
"檢點時打了「異常」的項目會自動列在這裡。改善好了，點「填寫改善」寫處理方式就能結案。同一個項目還沒結案前再異常，會記在同一件。": "Items marked \"Abnormal\" are listed here automatically. When fixed, tap \"Record fix\" and describe what was done to close it. Repeats before closing are added to the same issue.",
"檢點時打了「異常」的項目會自動轉到「異常追蹤」，改善好了填寫處理方式才算結案。": "Items marked \"Abnormal\" move to \"Issue tracking\" automatically. An issue closes only when you record how it was fixed.",
"檢點表": "Check forms",
