"每個工程一份，請廠商在施工前 3 個工作天填好。從您的 App 傳出去的連結，會先問您要不要帶入您是「員和承辦人員」。": "One per job; the contractor fills it 3 working days before work. Before sending, the app asks whether to add you as the person in charge.",
"每個工程一份，請廠商在施工前 3 個工作天填好。這個連結已經帶入您是「員和承辦人員」。": "One per job. The contractor fills it at least 3 working days before work. This link already lists you as the Yuanhe person in charge.",
"每個月結束後送出確認，確認後就鎖定。": "After each month, send it for confirmation; once confirmed it is locked.",
"每個月結束後，整課的紀錄一起送給單位負責人審核，任一位同仁送出即可。": "After each month, the whole section's records go to the supervisor for review. Any one person can send them.",
