"每日檢點表的「檢查人員簽章」在每天那一格，很窄，所以要一個直的簽名。請": "On the daily checklist the \"Inspector signature\" box for each day is narrow, so a vertical signature is needed. Please",
"每月": "Monthly",
"每月寄上個月各課的送審狀況（單位負責人、環安衛）": "Last month status for each unit, sent monthly (supervisors and EHS)",
"每月核准後照常自動歸檔": "Monthly records are still archived automatically after approval",
"每月核准後系統照常自動歸檔到 NAS。另外要資料時，到「設定 → 資料匯出」，勾選部門、月份範圍和檢點表，按「產生 PDF」。一個部門一個月一份，多份會打包成 zip 下載。還沒核准歸檔的月份要另外勾選才會匯出，PDF 上不會有單位負責人簽名，檔名註明「未簽核」。": "Records are still archived to the NAS automatically after each monthly approval. When you need records separately, go to \"Settings → Export records\", tick the departments, month range and check forms, then tap \"Create PDF\". One file per department per month; several files are downloaded as one zip. Months not yet approved are exported only if you tick that option; those PDFs carry no unit head signature and the file name is marked as not approved.",
"每月紀錄歸檔後寄給您，附有您簽名的檢點表（單位負責人附整份）": "Sent after each month is filed, with the forms you signed (supervisors get the full set)",
"每月至少巡一次（可輪流抽查部分區域），缺失用點的就能填好，系統自動開異常追蹤，紀錄存成 EF-00-012-B 放 NAS。": "Inspect at least once a month (you can rotate through areas). Findings are filled in by tapping; the system opens issue tracking and files the record as EF-00-012-B on the NAS.",
