"每月核准後照常自動歸檔": "บันทึกรายเดือนยังจัดเก็บอัตโนมัติหลังอนุมัติเหมือนเดิม",
"每月核准後系統照常自動歸檔到 NAS。另外要資料時，到「設定 → 資料匯出」，勾選部門、月份範圍和檢點表，按「產生 PDF」。一個部門一個月一份，多份會打包成 zip 下載。還沒核准歸檔的月份要另外勾選才會匯出，PDF 上不會有單位負責人簽名，檔名註明「未簽核」。": "หลังอนุมัติรายเดือน ระบบยังจัดเก็บลง NAS อัตโนมัติเหมือนเดิม ถ้าต้องการข้อมูลเพิ่ม ไปที่ \"ตั้งค่า → ส่งออกข้อมูล\" เลือกแผนก ช่วงเดือน และแบบฟอร์มตรวจ แล้วกด \"สร้าง PDF\" หนึ่งแผนกหนึ่งเดือนเป็นหนึ่งไฟล์ ถ้าหลายไฟล์จะรวมเป็น zip ให้ดาวน์โหลด เดือนที่ยังไม่อนุมัติจะส่งออกเฉพาะเมื่อเลือกตัวเลือกนั้น PDF จะไม่มีลายเซ็นหัวหน้าหน่วยงาน และชื่อไฟล์จะระบุว่ายังไม่อนุมัติ",
"每月紀錄歸檔後寄給您，附有您簽名的檢點表（單位負責人附整份）": "ส่งหลังเก็บบันทึกแต่ละเดือน แนบแบบตรวจที่คุณเซ็น (หัวหน้าได้ทั้งชุด)",
"每月至少巡一次（可輪流抽查部分區域），缺失用點的就能填好，系統自動開異常追蹤，紀錄存成 EF-00-012-B 放 NAS。": "ตรวจอย่างน้อยเดือนละครั้ง (สลับตรวจบางพื้นที่ได้) กรอกข้อบกพร่องได้ด้วยการแตะเลือก ระบบจะเปิดการติดตามปัญหาให้อัตโนมัติ และเก็บบันทึกเป็น EF-00-012-B ใน NAS",
