"這張表沒有「全部正常」，每一項都要自己勾；送出前要附 {0} 張以上現場照片、寫檢查過程紀要，單位負責人與環安衛審核時看得到。": "แบบนี้ไม่มี \"ปกติทั้งหมด\" ต้องติ๊กทุกข้อเอง แนบรูปหน้างานอย่างน้อย {0} รูปและเขียนบันทึกก่อนส่ง หัวหน้าและ EHS จะเห็น",
