"這支手機沒有這場會議的 QR Code（可能重新開過 App）。按下面產生新的，舊的會失效。": "โทรศัพท์นี้ไม่มี QR Code ของการประชุมนี้ (อาจเปิดแอปใหม่) กดด้านล่างเพื่อสร้างใหม่ อันเก่าจะใช้ไม่ได้",
