"這裡只管要不要寄 Email 到公司信箱": "ตรงนี้ตั้งแค่ว่าจะส่งอีเมลไปที่อีเมลบริษัทหรือไม่",
"這裡是另外要資料時用（例如勞檢、稽核要看某幾個月或某幾張表）。一個部門一個月一份 PDF，多份會打包成 zip 下載。": "ใช้เมื่อต้องการข้อมูลเพิ่มเติม (เช่น การตรวจแรงงานหรือการตรวจประเมินขอดูบางเดือนหรือบางแบบฟอร์ม) หนึ่งแผนกหนึ่งเดือนเป็น PDF หนึ่งไฟล์ ถ้าหลายไฟล์จะรวมเป็น zip ให้ดาวน์โหลด",
"這裡是本課已開放、但還沒指派給您的表。按「領取」會送申請給單位負責人，核准後就會出現在首頁。要取消領取請洽單位負責人。": "นี่คือแบบฟอร์มที่หน่วยงานเปิดไว้แต่ยังไม่ได้มอบหมายให้คุณ กด \"รับ\" เพื่อส่งคำขอถึงหัวหน้าหน่วยงาน เมื่ออนุมัติแล้วจะแสดงในหน้าแรก หากต้องการยกเลิกให้ติดต่อหัวหน้าหน่วยงาน",
"這裡是本課已開放、但還沒指派給您的表。領了之後就會出現在首頁，並記在後台「領取紀錄」。要取消領取請洽環安衛中心。": "แบบตรวจเหล่านี้เปิดให้แผนกแต่ยังไม่ได้มอบให้คุณ เมื่อรับแล้วจะแสดงในหน้าแรกและมีบันทึก ถ้าจะยกเลิกติดต่อศูนย์ EHS",
